INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-8-02', 'awl-8', 'Học thuật Sublist 8 · Bộ 2', 'Academic Word List, sublist 8', '#a974ff', 'GraduationCap', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 1, 'induce', 'gây ra; khiến, thúc đẩy (ai làm gì)', 'verb', '[{"en":"This medicine can induce drowsiness in some patients.","vi":"Loại thuốc này có thể gây buồn ngủ ở một số bệnh nhân."},{"en":"Higher wages may induce more workers to move to the city.","vi":"Mức lương cao hơn có thể khiến nhiều lao động chuyển đến thành phố hơn."},{"en":"Long-term stress can induce changes in the immune system.","vi":"Căng thẳng kéo dài có thể gây ra những thay đổi trong hệ miễn dịch."}]', '[{"phrase":"induce sleep"},{"phrase":"induce somebody to do something"},{"phrase":"stress-induced"}]', NULL, '/ɪnˈduːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/induc/induce__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 2, 'inevitable', 'không thể tránh khỏi; tất yếu', 'adjective', '[{"en":"Some job losses are inevitable when factories introduce new technology.","vi":"Khi các nhà máy áp dụng công nghệ mới, việc mất một số việc làm là không thể tránh khỏi."},{"en":"It was inevitable that prices would rise after the fuel shortage.","vi":"Giá cả tăng lên sau đợt thiếu hụt nhiên liệu là điều tất yếu."},{"en":"Delays are almost inevitable in a project of this size.","vi":"Chậm trễ gần như là không thể tránh khỏi trong một dự án quy mô như thế này."}]', '[{"phrase":"almost inevitable"},{"phrase":"inevitable consequence"},{"phrase":"it is inevitable that"}]', NULL, '/ɪnˈevɪtəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ine/inevi/inevitable__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 3, 'infrastructure', 'cơ sở hạ tầng', 'noun', '[{"en":"The government plans to invest heavily in transport infrastructure.","vi":"Chính phủ dự định đầu tư mạnh vào cơ sở hạ tầng giao thông."},{"en":"Many rural areas still lack basic infrastructure such as clean water.","vi":"Nhiều vùng nông thôn vẫn thiếu cơ sở hạ tầng cơ bản như nước sạch."},{"en":"Poor infrastructure makes it difficult for companies to move goods quickly.","vi":"Cơ sở hạ tầng yếu kém khiến các công ty khó vận chuyển hàng hóa nhanh chóng."}]', '[{"phrase":"transport infrastructure"},{"phrase":"basic infrastructure"},{"phrase":"invest in infrastructure"}]', NULL, '/ˈɪnfrəstrʌktʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infra/infrastructure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 4, 'inspect', 'kiểm tra; thanh tra', 'verb', '[{"en":"Officials inspect the factory every six months for safety problems.","vi":"Cán bộ thanh tra kiểm tra nhà máy sáu tháng một lần để phát hiện các vấn đề an toàn."},{"en":"The engineer carefully inspected the bridge for signs of damage.","vi":"Kỹ sư đã kiểm tra kỹ cây cầu để tìm dấu hiệu hư hỏng."},{"en":"All food products must be inspected before they leave the warehouse.","vi":"Tất cả sản phẩm thực phẩm phải được kiểm tra trước khi rời kho."}]', '[{"phrase":"carefully inspect"},{"phrase":"inspect for damage"},{"phrase":"inspect the premises"}]', NULL, '/ɪnˈspekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/inspe/inspect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 5, 'intense', 'mạnh mẽ, dữ dội; gay gắt, căng thẳng', 'adjective', '[{"en":"The company faces intense competition from cheaper foreign producers.","vi":"Công ty phải đối mặt với sự cạnh tranh gay gắt từ các nhà sản xuất nước ngoài có giá rẻ hơn."},{"en":"Kitchen staff must cope with intense heat throughout the day.","vi":"Nhân viên bếp phải chịu đựng cái nóng dữ dội suốt cả ngày."},{"en":"The proposal led to an intense debate among committee members.","vi":"Đề xuất này đã dẫn đến một cuộc tranh luận gay gắt giữa các thành viên hội đồng."}]', '[{"phrase":"intense competition"},{"phrase":"intense pressure"},{"phrase":"intense debate"},{"phrase":"intense heat"}]', NULL, '/ɪnˈtens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inten/intense__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 6, 'manipulate', 'thao túng; xử lý, điều khiển (khéo léo)', 'verb', '[{"en":"Some advertisements try to manipulate people into buying things they don’t need.","vi":"Một số quảng cáo tìm cách thao túng mọi người để họ mua những thứ không cần thiết."},{"en":"The researchers were accused of manipulating data to support their theory.","vi":"Các nhà nghiên cứu bị cáo buộc đã thao túng dữ liệu để củng cố lý thuyết của mình."},{"en":"Students learn how to manipulate images using computer software.","vi":"Sinh viên học cách xử lý hình ảnh bằng phần mềm máy tính."}]', '[{"phrase":"manipulate data"},{"phrase":"manipulate public opinion"},{"phrase":"manipulate somebody into"}]', NULL, '/məˈnɪpjuleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manip/manipulate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 7, 'minimise', 'giảm thiểu; giảm đến mức thấp nhất', 'verb', '[{"en":"We must take steps to minimise the risk of infection.","vi":"Chúng ta phải có biện pháp để giảm thiểu nguy cơ lây nhiễm."},{"en":"The new design minimises energy use without reducing performance.","vi":"Thiết kế mới giảm thiểu mức tiêu thụ năng lượng mà không làm giảm hiệu suất."},{"en":"Careful planning helped minimise disruption to local residents during construction.","vi":"Việc lên kế hoạch cẩn thận đã giúp giảm thiểu sự xáo trộn đối với cư dân địa phương trong quá trình xây dựng."}]', '[{"phrase":"minimise the risk"},{"phrase":"minimise costs"},{"phrase":"minimise the impact"},{"phrase":"minimise disruption"}]', 'Anh: minimise · Mỹ: minimize', NULL, NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 8, 'nuclear', '(thuộc) hạt nhân', 'adjective', '[{"en":"The country produces about a third of its electricity from nuclear power.","vi":"Quốc gia này sản xuất khoảng một phần ba lượng điện từ năng lượng hạt nhân."},{"en":"Engineers regularly check the safety systems at the nuclear power station.","vi":"Các kỹ sư thường xuyên kiểm tra hệ thống an toàn tại nhà máy điện hạt nhân."},{"en":"The storage of nuclear waste remains a serious environmental problem.","vi":"Việc lưu trữ chất thải hạt nhân vẫn là một vấn đề môi trường nghiêm trọng."}]', '[{"phrase":"nuclear power"},{"phrase":"nuclear energy"},{"phrase":"nuclear waste"},{"phrase":"nuclear power station"}]', NULL, '/ˈnuːkliər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nuc/nucle/nuclear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 9, 'offset', 'bù đắp; bù trừ', 'verb', '[{"en":"Strong sales in Asia helped offset losses in the European market.","vi":"Doanh số cao ở châu Á đã giúp bù đắp khoản lỗ tại thị trường châu Âu."},{"en":"The rise in costs was partly offset by lower taxes.","vi":"Việc chi phí tăng đã được bù đắp một phần nhờ thuế thấp hơn."},{"en":"Some companies plant trees to offset their carbon emissions.","vi":"Một số công ty trồng cây để bù đắp lượng khí thải carbon của họ."}]', '[{"phrase":"offset the cost"},{"phrase":"partly offset"},{"phrase":"offset losses"},{"phrase":"offset carbon emissions"}]', 'offset – offset – offset', '/ˈɔːfset/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offse/offset__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 10, 'paragraph', 'đoạn văn', 'noun', '[{"en":"Each paragraph in your essay should focus on one main idea.","vi":"Mỗi đoạn văn trong bài luận của bạn nên tập trung vào một ý chính."},{"en":"The author explains her method in the second paragraph of the introduction.","vi":"Tác giả giải thích phương pháp của mình ở đoạn thứ hai của phần mở đầu."},{"en":"Please add a short paragraph summarizing the main findings.","vi":"Vui lòng thêm một đoạn văn ngắn tóm tắt các phát hiện chính."}]', '[{"phrase":"opening paragraph"},{"phrase":"final paragraph"},{"phrase":"a short paragraph"},{"phrase":"previous paragraph"}]', NULL, '/ˈpærəɡræf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parag/paragraph__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 11, 'plus', 'cộng; cộng thêm, cùng với', 'preposition', '[{"en":"The ticket costs forty dollars, plus a small booking fee.","vi":"Vé có giá bốn mươi đô la, cộng thêm một khoản phí đặt chỗ nhỏ."},{"en":"Applicants need a degree plus two years of relevant work experience.","vi":"Ứng viên cần có bằng đại học cùng với hai năm kinh nghiệm làm việc liên quan."},{"en":"You will have to repay the loan plus interest within five years.","vi":"Bạn sẽ phải trả khoản vay cộng tiền lãi trong vòng năm năm."}]', '[{"phrase":"plus tax"},{"phrase":"plus interest"},{"phrase":"plus or minus"}]', NULL, '/plʌs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/plu/plus_/plus__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 12, 'practitioner', 'người hành nghề (y, luật…); người làm thực tiễn', 'noun', '[{"en":"Medical practitioners must renew their licenses every five years.","vi":"Người hành nghề y phải gia hạn giấy phép năm năm một lần."},{"en":"The workshop brings together researchers and practitioners from across the industry.","vi":"Hội thảo quy tụ các nhà nghiên cứu và những người làm thực tiễn từ khắp ngành."},{"en":"Patients should see a general practitioner before visiting a specialist.","vi":"Bệnh nhân nên khám bác sĩ đa khoa trước khi đến gặp bác sĩ chuyên khoa."}]', '[{"phrase":"medical practitioner"},{"phrase":"general practitioner"},{"phrase":"legal practitioner"},{"phrase":"health practitioner"}]', NULL, '/prækˈtɪʃənər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pra/pract/practitioner__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 13, 'predominant', 'chiếm ưu thế; chủ yếu', 'adjective', '[{"en":"English is the predominant language of international scientific journals.","vi":"Tiếng Anh là ngôn ngữ chiếm ưu thế trong các tạp chí khoa học quốc tế."},{"en":"Farming remains the predominant source of income in the region.","vi":"Nông nghiệp vẫn là nguồn thu nhập chủ yếu trong khu vực."},{"en":"Anxiety was the predominant feeling among staff after the merger was announced.","vi":"Lo lắng là tâm trạng chủ yếu của nhân viên sau khi việc sáp nhập được công bố."}]', '[{"phrase":"predominant role"},{"phrase":"predominant feature"},{"phrase":"predominant language"}]', NULL, '/prɪˈdɑːmɪnənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/predo/predominant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 14, 'prospect', 'triển vọng; khả năng (xảy ra)', 'noun', '[{"en":"Graduates with engineering degrees have excellent job prospects.","vi":"Sinh viên tốt nghiệp ngành kỹ thuật có triển vọng việc làm rất tốt."},{"en":"There is little prospect of an agreement before the end of the year.","vi":"Có rất ít khả năng đạt được thỏa thuận trước cuối năm."},{"en":"The prospect of higher interest rates worries many small business owners.","vi":"Khả năng lãi suất tăng khiến nhiều chủ doanh nghiệp nhỏ lo lắng."}]', '[{"phrase":"job prospects"},{"phrase":"career prospects"},{"phrase":"long-term prospects"},{"phrase":"little prospect of"}]', NULL, '/ˈprɑːspekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prosp/prospect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 15, 'radical', 'căn bản, triệt để; cấp tiến', 'adjective', '[{"en":"The industry needs radical changes to reduce its carbon emissions.","vi":"Ngành công nghiệp này cần những thay đổi căn bản để giảm lượng khí thải carbon."},{"en":"The report proposes a radical reform of the tax system.","vi":"Báo cáo đề xuất một cuộc cải cách triệt để hệ thống thuế."},{"en":"At the time, his ideas about education were considered radical.","vi":"Vào thời điểm đó, những ý tưởng của ông về giáo dục bị coi là cấp tiến."}]', '[{"phrase":"radical change"},{"phrase":"radical reform"},{"phrase":"radical ideas"},{"phrase":"radical approach"}]', NULL, '/ˈrædɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rad/radic/radical__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 16, 'random', 'ngẫu nhiên', 'adjective', '[{"en":"The researchers selected a random sample of 500 households.","vi":"Các nhà nghiên cứu đã chọn một mẫu ngẫu nhiên gồm 500 hộ gia đình."},{"en":"Security staff carry out random checks on bags at the entrance.","vi":"Nhân viên an ninh tiến hành kiểm tra túi xách ngẫu nhiên tại lối vào."},{"en":"The winners will be chosen at random from all the entries.","vi":"Người thắng cuộc sẽ được chọn ngẫu nhiên từ tất cả các bài dự thi."}]', '[{"phrase":"random sample"},{"phrase":"at random"},{"phrase":"random checks"},{"phrase":"random selection"}]', NULL, '/ˈrændəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ran/rando/random__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 17, 'reinforce', 'củng cố, tăng cường; gia cố', 'verb', '[{"en":"The study’s findings reinforce the importance of early education.","vi":"Những phát hiện của nghiên cứu càng củng cố tầm quan trọng của giáo dục sớm."},{"en":"Regular practice helps reinforce what students have learned in class.","vi":"Luyện tập thường xuyên giúp củng cố những gì học sinh đã học trên lớp."},{"en":"Engineers reinforced the walls with steel to protect against earthquakes.","vi":"Các kỹ sư đã gia cố tường bằng thép để chống động đất."}]', '[{"phrase":"reinforce the idea"},{"phrase":"reinforce the message"},{"phrase":"reinforced concrete"}]', NULL, '/ˌriːɪnˈfɔːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rei/reinf/reinforce__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 18, 'restore', 'khôi phục; phục hồi, trùng tu', 'verb', '[{"en":"Engineers worked through the night to restore power to the city.","vi":"Các kỹ sư đã làm việc suốt đêm để khôi phục điện cho thành phố."},{"en":"The old theater has been carefully restored to its original condition.","vi":"Nhà hát cũ đã được trùng tu cẩn thận, trở lại nguyên trạng ban đầu."},{"en":"The new management team hopes to restore confidence among investors.","vi":"Ban quản lý mới hy vọng khôi phục niềm tin của các nhà đầu tư."}]', '[{"phrase":"restore confidence"},{"phrase":"restore order"},{"phrase":"restore power"},{"phrase":"fully restored"}]', NULL, '/rɪˈstɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resto/restore__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 19, 'revise', 'sửa đổi; điều chỉnh', 'verb', '[{"en":"The bank has revised its growth forecast for next year.","vi":"Ngân hàng đã điều chỉnh dự báo tăng trưởng cho năm tới."},{"en":"Please revise your essay and submit it again by Friday.","vi":"Vui lòng sửa lại bài luận và nộp lại trước thứ Sáu."},{"en":"The company revised its safety rules after the accident.","vi":"Công ty đã sửa đổi các quy định an toàn sau vụ tai nạn."}]', '[{"phrase":"revise a forecast"},{"phrase":"revise estimates"},{"phrase":"revised edition"},{"phrase":"revised version"}]', NULL, '/rɪˈvaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revis/revise__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 20, 'schedule', 'lịch trình, thời gian biểu; kế hoạch (tiến độ)', 'noun', '[{"en":"The project is running two weeks behind schedule.","vi":"Dự án đang chậm hai tuần so với kế hoạch."},{"en":"Check the train schedule before you leave the office.","vi":"Hãy xem lịch tàu chạy trước khi bạn rời văn phòng."},{"en":"Doctors often work a demanding schedule with very long shifts.","vi":"Các bác sĩ thường làm việc theo lịch trình khắt khe với những ca trực rất dài."}]', '[{"phrase":"behind schedule"},{"phrase":"on schedule"},{"phrase":"busy schedule"},{"phrase":"tight schedule"}]', NULL, '/ˈskedʒuːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/sched/schedule__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 21, 'tense', 'căng thẳng', 'adjective', '[{"en":"Relations between management and the union have been tense for months.","vi":"Quan hệ giữa ban quản lý và công đoàn đã căng thẳng suốt nhiều tháng."},{"en":"The meeting was tense because nobody could agree on the budget.","vi":"Cuộc họp diễn ra căng thẳng vì không ai thống nhất được về ngân sách."},{"en":"Many students feel tense before important exams.","vi":"Nhiều sinh viên cảm thấy căng thẳng trước những kỳ thi quan trọng."}]', '[{"phrase":"tense atmosphere"},{"phrase":"tense situation"},{"phrase":"feel tense"}]', 'tense (n): thì (ngữ pháp)', '/tens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tense/tense__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 22, 'terminate', 'chấm dứt; kết thúc', 'verb', '[{"en":"The company terminated the contract after repeated delays.","vi":"Công ty đã chấm dứt hợp đồng sau nhiều lần chậm trễ."},{"en":"Either party may terminate the agreement with thirty days’ notice.","vi":"Bất kỳ bên nào cũng có thể chấm dứt thỏa thuận nếu báo trước ba mươi ngày."},{"en":"This train terminates at the central station.","vi":"Chuyến tàu này kết thúc hành trình tại ga trung tâm."}]', '[{"phrase":"terminate a contract"},{"phrase":"terminate an agreement"},{"phrase":"terminate employment"}]', NULL, '/ˈtɜːrmɪneɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ter/termi/terminate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 23, 'theme', 'chủ đề', 'noun', '[{"en":"Climate change was the main theme of this year’s conference.","vi":"Biến đổi khí hậu là chủ đề chính của hội nghị năm nay."},{"en":"Several common themes emerged from the interviews with teachers.","vi":"Một số chủ đề chung đã nổi lên từ các cuộc phỏng vấn giáo viên."},{"en":"The novel explores themes of loss and identity.","vi":"Cuốn tiểu thuyết khai thác các chủ đề về mất mát và bản sắc."}]', '[{"phrase":"main theme"},{"phrase":"central theme"},{"phrase":"common theme"},{"phrase":"recurring theme"}]', NULL, '/θiːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/theme/theme__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 24, 'thereby', 'do đó, nhờ đó; bằng cách đó', 'adverb', '[{"en":"The company cut its prices, thereby attracting many new customers.","vi":"Công ty đã giảm giá, nhờ đó thu hút được nhiều khách hàng mới."},{"en":"Trees absorb carbon dioxide, thereby reducing the effects of climate change.","vi":"Cây xanh hấp thụ khí carbon dioxide, qua đó làm giảm tác động của biến đổi khí hậu."},{"en":"The new system saves time and thereby lowers operating costs.","vi":"Hệ thống mới tiết kiệm thời gian và do đó giảm chi phí vận hành."}]', '[{"phrase":"thereby reducing"},{"phrase":"thereby increasing"},{"phrase":"thereby allowing"}]', NULL, '/ˌðerˈbaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/there/thereby__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 25, 'uniform', 'đồng nhất, đồng đều; thống nhất', 'adjective', '[{"en":"The rules should be applied in a uniform way across all departments.","vi":"Các quy định cần được áp dụng một cách thống nhất ở tất cả các phòng ban."},{"en":"The samples were heated to a uniform temperature of 80 degrees.","vi":"Các mẫu được nung nóng đồng đều ở nhiệt độ 80 độ."},{"en":"Economic growth has not been uniform across the country.","vi":"Tăng trưởng kinh tế không đồng đều trên cả nước."}]', '[{"phrase":"uniform standards"},{"phrase":"uniform rate"},{"phrase":"uniform temperature"},{"phrase":"uniform distribution"}]', 'uniform (n): đồng phục', '/ˈjuːnɪfɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unifo/uniform__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 26, 'vehicle', 'xe, phương tiện (giao thông); phương tiện (truyền tải)', 'noun', '[{"en":"Electric vehicles are becoming cheaper and more popular.","vi":"Xe điện ngày càng rẻ hơn và phổ biến hơn."},{"en":"Police stopped several vehicles on the main road this morning.","vi":"Sáng nay cảnh sát đã dừng một số phương tiện trên đường chính."},{"en":"Social media has become a powerful vehicle for marketing new products.","vi":"Mạng xã hội đã trở thành một phương tiện hữu hiệu để quảng bá sản phẩm mới."}]', '[{"phrase":"electric vehicle"},{"phrase":"motor vehicle"},{"phrase":"commercial vehicle"},{"phrase":"vehicle for"}]', NULL, '/ˈviːəkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/veh/vehic/vehicle__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 27, 'via', 'qua, thông qua; đi qua (nơi nào)', 'preposition', '[{"en":"Participants can complete the survey via email or by phone.","vi":"Người tham gia có thể hoàn thành khảo sát qua email hoặc qua điện thoại."},{"en":"The goods are shipped to Europe via a port in the south.","vi":"Hàng hóa được vận chuyển sang châu Âu qua một cảng ở phía nam."},{"en":"The lecture will be broadcast live via the university website.","vi":"Bài giảng sẽ được phát trực tiếp qua trang web của trường đại học."}]', '[{"phrase":"via email"},{"phrase":"via the internet"},{"phrase":"via satellite"}]', NULL, '/ˈvaɪə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/via/via__/via__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 28, 'virtual', 'ảo, trực tuyến; gần như, hầu như', 'adjective', '[{"en":"Many companies now hold virtual meetings instead of sending staff abroad.","vi":"Nhiều công ty hiện tổ chức các cuộc họp trực tuyến thay vì cử nhân viên ra nước ngoài."},{"en":"Students can explore the museum through a virtual tour.","vi":"Học sinh có thể khám phá bảo tàng qua một chuyến tham quan ảo."},{"en":"The strike brought the city’s transport system to a virtual standstill.","vi":"Cuộc đình công đã khiến hệ thống giao thông của thành phố gần như tê liệt."}]', '[{"phrase":"virtual reality"},{"phrase":"virtual meeting"},{"phrase":"virtual tour"},{"phrase":"virtual standstill"}]', NULL, '/ˈvɜːrtʃuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vir/virtu/virtual__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 29, 'visual', '(thuộc) thị giác; trực quan, bằng hình ảnh', 'adjective', '[{"en":"Charts and other visual aids make presentations easier to follow.","vi":"Biểu đồ và các phương tiện trực quan khác giúp bài thuyết trình dễ theo dõi hơn."},{"en":"The study measured changes in patients’ visual memory over time.","vi":"Nghiên cứu đã đo những thay đổi về trí nhớ thị giác của bệnh nhân theo thời gian."},{"en":"The website’s visual design was updated to attract younger users.","vi":"Thiết kế hình ảnh của trang web đã được cập nhật để thu hút người dùng trẻ hơn."}]', '[{"phrase":"visual aids"},{"phrase":"visual arts"},{"phrase":"visual effects"},{"phrase":"visual impairment"}]', NULL, '/ˈvɪʒuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visua/visual__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-02', 30, 'widespread', 'phổ biến, lan rộng; trên diện rộng', 'adjective', '[{"en":"Smartphone use is now widespread among older adults.","vi":"Việc sử dụng điện thoại thông minh hiện đã phổ biến ở người lớn tuổi."},{"en":"Heavy rain caused widespread flooding across the region.","vi":"Mưa lớn đã gây ngập lụt trên diện rộng khắp khu vực."},{"en":"The new policy has received widespread support from teachers.","vi":"Chính sách mới đã nhận được sự ủng hộ rộng rãi từ giáo viên."}]', '[{"phrase":"widespread support"},{"phrase":"widespread use"},{"phrase":"widespread concern"}]', NULL, '/ˈwaɪdspred/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wid/wides/widespread__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-9-01', 'awl-9', 'Học thuật Sublist 9 · Bộ 1', 'Academic Word List, sublist 9', '#a974ff', 'GraduationCap', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 1, 'accommodate', 'chứa được; đáp ứng; bố trí chỗ ở', 'verb', '[{"en":"The new lecture hall can accommodate up to five hundred students.","vi":"Giảng đường mới có thể chứa tới năm trăm sinh viên."},{"en":"We try to accommodate the needs of students with disabilities.","vi":"Chúng tôi cố gắng đáp ứng nhu cầu của sinh viên khuyết tật."},{"en":"Visiting researchers are accommodated in apartments near the campus.","vi":"Các nhà nghiên cứu thỉnh giảng được bố trí ở trong các căn hộ gần trường."}]', '[{"phrase":"accommodate the needs of"},{"phrase":"accommodate changes"},{"phrase":"easily accommodate"}]', NULL, '/əˈkɑːmədeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accom/accommodate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 2, 'analogy', 'sự so sánh tương đồng; phép loại suy', 'noun', '[{"en":"The teacher used a simple analogy to explain how the heart works.","vi":"Giáo viên dùng một phép so sánh đơn giản để giải thích cách tim hoạt động."},{"en":"Some economists draw an analogy between the two financial crises.","vi":"Một số nhà kinh tế học so sánh tương đồng giữa hai cuộc khủng hoảng tài chính."},{"en":"By analogy, a computer''s memory is often compared to a library.","vi":"Theo phép loại suy, bộ nhớ máy tính thường được ví như một thư viện."}]', '[{"phrase":"draw an analogy"},{"phrase":"a useful analogy"},{"phrase":"by analogy"},{"phrase":"analogy between"}]', 'draw an analogy between A and B: so sánh A với B', '/əˈnælədʒi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ana/analo/analogy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 3, 'anticipate', 'dự đoán; lường trước', 'verb', '[{"en":"Few experts anticipated such a sharp rise in energy prices.","vi":"Rất ít chuyên gia dự đoán được giá năng lượng sẽ tăng mạnh như vậy."},{"en":"Good managers anticipate problems before they become serious.","vi":"Những nhà quản lý giỏi lường trước vấn đề trước khi chúng trở nên nghiêm trọng."},{"en":"The project took much longer than we had anticipated.","vi":"Dự án mất nhiều thời gian hơn nhiều so với chúng tôi đã dự tính."}]', '[{"phrase":"anticipate problems"},{"phrase":"anticipate demand"},{"phrase":"than anticipated"},{"phrase":"widely anticipated"}]', 'anticipate + V-ing (không dùng to V)', '/ænˈtɪsɪpeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ant/antic/anticipate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 4, 'assure', 'cam đoan; đảm bảo với ai; trấn an', 'verb', '[{"en":"The manager assured staff that no jobs would be lost.","vi":"Người quản lý cam đoan với nhân viên rằng sẽ không ai bị mất việc."},{"en":"I can assure you that your data will be kept private.","vi":"Tôi có thể đảm bảo với bạn rằng dữ liệu của bạn sẽ được giữ bí mật."},{"en":"Officials assured residents that the tap water was safe to drink.","vi":"Giới chức trấn an người dân rằng nước máy an toàn để uống."}]', '[{"phrase":"assure somebody that"},{"phrase":"I can assure you"},{"phrase":"rest assured"}]', 'assure (cam đoan với ai) ≠ ensure (đảm bảo điều gì xảy ra)', '/əˈʃʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assur/assure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 5, 'attain', 'đạt được; giành được', 'verb', '[{"en":"Only a third of the students attained the required grade.","vi":"Chỉ một phần ba số sinh viên đạt được điểm yêu cầu."},{"en":"The company has attained its goal of cutting emissions by half.","vi":"Công ty đã đạt được mục tiêu cắt giảm một nửa lượng khí thải."},{"en":"Women in the region are now attaining higher levels of education.","vi":"Phụ nữ trong khu vực hiện đang đạt tới trình độ học vấn cao hơn."}]', '[{"phrase":"attain a goal"},{"phrase":"attain a level"},{"phrase":"attain a standard"}]', NULL, '/əˈteɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attai/attain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 6, 'behalf', 'thay mặt; nhân danh', 'noun', '[{"en":"She accepted the award on behalf of the whole research team.","vi":"Cô ấy thay mặt cả nhóm nghiên cứu nhận giải thưởng."},{"en":"Lawyers acting on behalf of the workers have filed a complaint.","vi":"Các luật sư đại diện cho người lao động đã nộp đơn khiếu nại."},{"en":"I would like to thank you all on behalf of the university.","vi":"Tôi xin thay mặt nhà trường cảm ơn tất cả các bạn."}]', '[{"phrase":"on behalf of"},{"phrase":"act on behalf of"},{"phrase":"on somebody''s behalf"}]', 'Hầu như chỉ dùng trong cụm on behalf of / on somebody''s behalf', '/bɪˈhæf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/beh/behal/behalf__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 7, 'bulk', 'phần lớn; khối lượng lớn', 'noun', '[{"en":"The bulk of the funding comes from government grants.","vi":"Phần lớn kinh phí đến từ các khoản tài trợ của chính phủ."},{"en":"Students spend the bulk of their time on independent study.","vi":"Sinh viên dành phần lớn thời gian cho việc tự học."},{"en":"Restaurants usually save money by buying rice and oil in bulk.","vi":"Các nhà hàng thường tiết kiệm tiền bằng cách mua gạo và dầu với số lượng lớn."}]', '[{"phrase":"the bulk of"},{"phrase":"buy in bulk"},{"phrase":"bulk purchase"}]', 'the bulk of + danh từ: phần lớn của…', '/bʌlk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bul/bulk_/bulk__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 8, 'cease', 'ngừng; chấm dứt', 'verb', '[{"en":"The factory ceased production after the company went bankrupt.","vi":"Nhà máy ngừng sản xuất sau khi công ty phá sản."},{"en":"Fighting in the border area ceased early this morning.","vi":"Giao tranh ở khu vực biên giới đã chấm dứt vào sáng sớm nay."},{"en":"The progress of modern medicine never ceases to amaze me.","vi":"Sự tiến bộ của y học hiện đại không bao giờ thôi khiến tôi kinh ngạc."}]', '[{"phrase":"cease production"},{"phrase":"cease operations"},{"phrase":"cease to exist"},{"phrase":"never cease to amaze"}]', 'Trang trọng hơn stop; cease to V hoặc cease + V-ing', '/siːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cea/cease/cease__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 9, 'coherent', 'mạch lạc; chặt chẽ; nhất quán', 'adjective', '[{"en":"A good essay presents a clear and coherent argument.","vi":"Một bài luận hay trình bày lập luận rõ ràng và chặt chẽ."},{"en":"The government still lacks a coherent strategy for reducing poverty.","vi":"Chính phủ vẫn thiếu một chiến lược nhất quán để giảm nghèo."},{"en":"After the accident, he was too confused to give a coherent answer.","vi":"Sau tai nạn, anh ấy quá bối rối nên không thể trả lời mạch lạc."}]', '[{"phrase":"coherent argument"},{"phrase":"coherent strategy"},{"phrase":"coherent policy"},{"phrase":"coherent whole"}]', NULL, '/kəʊˈhɪrənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coh/coher/coherent__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 10, 'coincide', 'xảy ra cùng lúc; trùng với; trùng khớp', 'verb', '[{"en":"The book''s release was timed to coincide with the conference.","vi":"Việc phát hành cuốn sách được sắp xếp trùng với thời điểm diễn ra hội nghị."},{"en":"The rise in crime coincided with a sharp increase in unemployment.","vi":"Tình trạng tội phạm gia tăng xảy ra cùng lúc với tỷ lệ thất nghiệp tăng mạnh."},{"en":"Their views on the issue do not always coincide.","vi":"Quan điểm của họ về vấn đề này không phải lúc nào cũng trùng khớp."}]', '[{"phrase":"coincide with"},{"phrase":"timed to coincide with"},{"phrase":"views coincide"}]', 'coincide with something', '/ˌkəʊɪnˈsaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coi/coinc/coincide__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 11, 'commence', 'bắt đầu; khởi công', 'verb', '[{"en":"Construction of the new hospital will commence next spring.","vi":"Việc xây dựng bệnh viện mới sẽ khởi công vào mùa xuân tới."},{"en":"The trial commenced two weeks after the investigation ended.","vi":"Phiên tòa bắt đầu hai tuần sau khi cuộc điều tra kết thúc."},{"en":"Students must register before classes commence in September.","vi":"Sinh viên phải đăng ký trước khi các lớp học bắt đầu vào tháng Chín."}]', '[{"phrase":"commence work"},{"phrase":"commence operations"},{"phrase":"commence construction"}]', 'Trang trọng hơn begin / start', '/kəˈmens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comme/commence__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 12, 'compatible', 'tương thích; phù hợp; hợp nhau', 'adjective', '[{"en":"Make sure the software is compatible with your operating system.","vi":"Hãy đảm bảo phần mềm tương thích với hệ điều hành của bạn."},{"en":"Economic growth must be compatible with protecting the environment.","vi":"Tăng trưởng kinh tế phải phù hợp với việc bảo vệ môi trường."},{"en":"The two colleagues were never really compatible as a team.","vi":"Hai đồng nghiệp đó chưa bao giờ thực sự hợp nhau khi làm việc nhóm."}]', '[{"phrase":"compatible with"},{"phrase":"fully compatible"},{"phrase":"compatible software"}]', 'compatible with; trái nghĩa: incompatible', '/kəmˈpætəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compa/compatible__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 13, 'concurrent', 'đồng thời; diễn ra cùng lúc', 'adjective', '[{"en":"The conference offers several concurrent sessions each afternoon.","vi":"Hội nghị tổ chức nhiều phiên họp diễn ra đồng thời vào mỗi buổi chiều."},{"en":"Patients with concurrent illnesses often need more complex treatment.","vi":"Bệnh nhân mắc nhiều bệnh cùng lúc thường cần điều trị phức tạp hơn."},{"en":"The study was concurrent with a wider survey of local schools.","vi":"Nghiên cứu này diễn ra đồng thời với một khảo sát rộng hơn ở các trường địa phương."}]', '[{"phrase":"concurrent sessions"},{"phrase":"concurrent with"},{"phrase":"concurrent use"}]', 'Trạng từ concurrently: một cách đồng thời', '/kənˈkɜːrənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcurrent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 14, 'confine', 'giới hạn; hạn chế; nhốt', 'verb', '[{"en":"Please confine your comments to the topic under discussion.","vi":"Vui lòng giới hạn ý kiến của bạn trong chủ đề đang thảo luận."},{"en":"The problem is by no means confined to large cities.","vi":"Vấn đề này hoàn toàn không chỉ giới hạn ở các thành phố lớn."},{"en":"The animals were confined in small cages for most of the day.","vi":"Những con vật bị nhốt trong các lồng nhỏ gần như cả ngày."}]', '[{"phrase":"confine something to"},{"phrase":"be confined to"},{"phrase":"confined space"}]', 'confine something to something; be confined to', '/kənˈfaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 15, 'controversy', 'cuộc tranh cãi; sự tranh luận', 'noun', '[{"en":"The new tax caused a great deal of controversy among business owners.","vi":"Loại thuế mới gây ra rất nhiều tranh cãi trong giới chủ doanh nghiệp."},{"en":"There is still controversy over the safety of the drug.","vi":"Vẫn còn tranh cãi về mức độ an toàn của loại thuốc này."},{"en":"The study sparked a controversy that lasted for several years.","vi":"Nghiên cứu đó đã làm dấy lên một cuộc tranh cãi kéo dài nhiều năm."}]', '[{"phrase":"cause controversy"},{"phrase":"spark controversy"},{"phrase":"controversy over"},{"phrase":"considerable controversy"}]', 'controversy over / about something', '/ˈkɑːntrəvɜːrsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontroversy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 16, 'converse', 'điều ngược lại', 'noun', '[{"en":"Wealthy people tend to live longer, but the converse is also true.","vi":"Người giàu thường sống lâu hơn, nhưng điều ngược lại cũng đúng."},{"en":"Some students work better alone; for others the converse applies.","vi":"Một số sinh viên làm việc một mình tốt hơn; với những người khác thì ngược lại."},{"en":"The data supported neither his claim nor the converse of it.","vi":"Dữ liệu không ủng hộ nhận định của ông ấy, cũng không ủng hộ điều ngược lại."}]', '[{"phrase":"the converse is true"},{"phrase":"the converse applies"},{"phrase":"the converse of"}]', 'Thường dùng: the converse; converse (v) còn nghĩa là trò chuyện', '/kənˈvɜːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconverse__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 17, 'device', 'thiết bị; dụng cụ; biện pháp, thủ pháp', 'noun', '[{"en":"Please switch off all electronic devices during the exam.","vi":"Vui lòng tắt tất cả thiết bị điện tử trong khi làm bài thi."},{"en":"The hospital uses a new device to monitor patients'' heart rates.","vi":"Bệnh viện sử dụng một thiết bị mới để theo dõi nhịp tim của bệnh nhân."},{"en":"Repetition is a common device in political speeches.","vi":"Sự lặp lại là một thủ pháp thường gặp trong các bài diễn văn chính trị."}]', '[{"phrase":"electronic device"},{"phrase":"mobile device"},{"phrase":"medical device"},{"phrase":"literary device"}]', 'device (n) ≠ devise (v: nghĩ ra, sáng chế)', '/dɪˈvaɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devic/device__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 18, 'devote', 'dành (thời gian, công sức); cống hiến', 'verb', '[{"en":"She has devoted her career to studying climate change.","vi":"Cô ấy đã cống hiến cả sự nghiệp cho việc nghiên cứu biến đổi khí hậu."},{"en":"The report devotes an entire chapter to health care costs.","vi":"Báo cáo dành trọn một chương cho chi phí chăm sóc sức khỏe."},{"en":"Teachers should devote more time to helping weaker students.","vi":"Giáo viên nên dành nhiều thời gian hơn để giúp đỡ các học sinh yếu."}]', '[{"phrase":"devote time to"},{"phrase":"devote attention to"},{"phrase":"devote resources to"},{"phrase":"devote yourself to"}]', 'devote something to + danh từ / V-ing', '/dɪˈvəʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devot/devote__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 19, 'diminish', 'giảm bớt; suy giảm; làm giảm', 'verb', '[{"en":"The risk of infection diminishes as the patient''s immune system recovers.","vi":"Nguy cơ nhiễm trùng giảm dần khi hệ miễn dịch của bệnh nhân hồi phục."},{"en":"Rising prices have diminished the value of their savings.","vi":"Giá cả tăng cao đã làm giảm giá trị khoản tiết kiệm của họ."},{"en":"Public interest in the story diminished after a few weeks.","vi":"Sự quan tâm của công chúng đối với câu chuyện giảm đi sau vài tuần."}]', '[{"phrase":"diminish the value"},{"phrase":"diminish over time"},{"phrase":"greatly diminish"},{"phrase":"diminishing returns"}]', NULL, '/dɪˈmɪnɪʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dim/dimin/diminish__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 20, 'distort', 'bóp méo; xuyên tạc; làm biến dạng', 'verb', '[{"en":"The newspaper was accused of distorting the facts.","vi":"Tờ báo bị cáo buộc xuyên tạc sự thật."},{"en":"A few extreme values can distort the results of a small study.","vi":"Một vài giá trị cực đoan có thể làm sai lệch kết quả của một nghiên cứu nhỏ."},{"en":"Heat rising from the road distorted the image of the cars ahead.","vi":"Hơi nóng bốc lên từ mặt đường làm biến dạng hình ảnh những chiếc xe phía trước."}]', '[{"phrase":"distort the truth"},{"phrase":"distort the facts"},{"phrase":"distort the results"},{"phrase":"seriously distort"}]', NULL, '/dɪˈstɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disto/distort__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 21, 'duration', 'thời lượng; khoảng thời gian kéo dài', 'noun', '[{"en":"The average duration of the treatment is six months.","vi":"Thời gian điều trị trung bình là sáu tháng."},{"en":"Phones must stay switched off for the duration of the exam.","vi":"Điện thoại phải tắt trong suốt thời gian làm bài thi."},{"en":"Researchers recorded the duration of each conversation in minutes.","vi":"Các nhà nghiên cứu ghi lại thời lượng của mỗi cuộc trò chuyện tính bằng phút."}]', '[{"phrase":"for the duration of"},{"phrase":"average duration"},{"phrase":"short duration"},{"phrase":"duration of the course"}]', NULL, '/duˈreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dur/durat/duration__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 22, 'erode', 'xói mòn; làm suy giảm dần', 'verb', '[{"en":"Strong waves have eroded large parts of the coastline.","vi":"Những con sóng mạnh đã làm xói mòn nhiều đoạn bờ biển."},{"en":"High inflation is steadily eroding people''s purchasing power.","vi":"Lạm phát cao đang dần làm suy giảm sức mua của người dân."},{"en":"Repeated scandals have eroded public trust in the banking system.","vi":"Những vụ bê bối liên tiếp đã làm xói mòn lòng tin của công chúng vào hệ thống ngân hàng."}]', '[{"phrase":"erode confidence"},{"phrase":"erode trust"},{"phrase":"gradually erode"},{"phrase":"erode the coastline"}]', NULL, '/ɪˈrəʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ero/erode/erode__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 23, 'ethic', 'đạo đức; nguyên tắc đạo đức', 'noun', '[{"en":"Employers value graduates with a strong work ethic.","vi":"Nhà tuyển dụng đánh giá cao những sinh viên tốt nghiệp có tinh thần làm việc nghiêm túc."},{"en":"All researchers here must follow a strict code of ethics.","vi":"Tất cả các nhà nghiên cứu ở đây phải tuân theo một bộ quy tắc đạo đức nghiêm ngặt."},{"en":"The course examines the ethics of using animals in medical research.","vi":"Khóa học xem xét vấn đề đạo đức của việc dùng động vật trong nghiên cứu y học."}]', '[{"phrase":"work ethic"},{"phrase":"code of ethics"},{"phrase":"professional ethics"},{"phrase":"medical ethics"}]', 'Thường dùng số nhiều: ethics (đạo đức học; quy tắc đạo đức)', '/ˈeθɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eth/ethic/ethic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 24, 'format', 'định dạng; hình thức trình bày', 'noun', '[{"en":"Please submit your assignment in PDF format.","vi":"Vui lòng nộp bài tập ở định dạng PDF."},{"en":"The exam will follow the same format as last year.","vi":"Bài thi sẽ theo hình thức giống như năm ngoái."},{"en":"Many journals now publish articles in both print and digital formats.","vi":"Nhiều tạp chí hiện nay xuất bản bài báo ở cả dạng in và dạng số."}]', '[{"phrase":"file format"},{"phrase":"digital format"},{"phrase":"in a format"},{"phrase":"change the format"}]', NULL, '/ˈfɔːrmæt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forma/format__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 25, 'found', 'thành lập; sáng lập; dựa trên', 'verb', '[{"en":"The university was founded in 1850 by a group of doctors.","vi":"Trường đại học được một nhóm bác sĩ thành lập vào năm 1850."},{"en":"She left her job to found a small software company.","vi":"Cô ấy nghỉ việc để sáng lập một công ty phần mềm nhỏ."},{"en":"Their theory is founded on decades of careful observation.","vi":"Lý thuyết của họ dựa trên hàng chục năm quan sát cẩn thận."}]', '[{"phrase":"found a company"},{"phrase":"founded in"},{"phrase":"be founded on"},{"phrase":"newly founded"}]', 'found – founded – founded (khác find – found – found)', '/faʊnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fou/found/found__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 26, 'inherent', 'vốn có; cố hữu; bẩm sinh', 'adjective', '[{"en":"Every investment in the stock market carries some inherent risk.","vi":"Mọi khoản đầu tư vào thị trường chứng khoán đều mang rủi ro vốn có."},{"en":"The study discusses problems inherent in using online surveys.","vi":"Nghiên cứu bàn về những vấn đề cố hữu khi sử dụng khảo sát trực tuyến."},{"en":"Some psychologists argue that the ability to learn language is inherent.","vi":"Một số nhà tâm lý học cho rằng khả năng học ngôn ngữ là bẩm sinh."}]', '[{"phrase":"inherent risk"},{"phrase":"inherent in"},{"phrase":"inherent weakness"},{"phrase":"inherent problem"}]', 'inherent in something', '/ɪnˈherənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inh/inher/inherent__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 27, 'insight', 'sự hiểu biết sâu sắc; cái nhìn sâu sắc', 'noun', '[{"en":"The interviews gave us valuable insight into how customers make decisions.","vi":"Các cuộc phỏng vấn cho chúng tôi hiểu biết sâu sắc về cách khách hàng ra quyết định."},{"en":"Her book offers new insights into the causes of poverty.","vi":"Cuốn sách của cô ấy đưa ra những góc nhìn sâu sắc mới về nguyên nhân của nghèo đói."},{"en":"Working abroad gave him real insight into other cultures.","vi":"Làm việc ở nước ngoài giúp anh ấy thực sự hiểu sâu về các nền văn hóa khác."}]', '[{"phrase":"insight into"},{"phrase":"gain insight"},{"phrase":"provide insight"},{"phrase":"valuable insight"}]', 'insight into something', '/ˈɪnsaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insig/insight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 28, 'integral', 'không thể thiếu; thiết yếu; gắn liền', 'adjective', '[{"en":"Practical training is an integral part of the nursing course.","vi":"Thực hành là một phần không thể thiếu của khóa học điều dưỡng."},{"en":"Local farmers played an integral role in the success of the project.","vi":"Nông dân địa phương đóng vai trò thiết yếu trong thành công của dự án."},{"en":"Music has always been integral to the country''s culture.","vi":"Âm nhạc luôn gắn liền với văn hóa của đất nước này."}]', '[{"phrase":"integral part"},{"phrase":"integral role"},{"phrase":"integral to"},{"phrase":"integral component"}]', 'integral to something', '/ˈɪntɪɡrəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/integ/integral__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 29, 'intermediate', 'trung cấp; trung gian', 'adjective', '[{"en":"This course is designed for students at an intermediate level.","vi":"Khóa học này được thiết kế cho học viên ở trình độ trung cấp."},{"en":"The chemical passes through several intermediate stages before it becomes stable.","vi":"Hóa chất này trải qua nhiều giai đoạn trung gian trước khi trở nên ổn định."},{"en":"Many small factories produce intermediate goods for larger manufacturers.","vi":"Nhiều nhà máy nhỏ sản xuất hàng hóa trung gian cho các nhà sản xuất lớn hơn."}]', '[{"phrase":"intermediate level"},{"phrase":"intermediate stage"},{"phrase":"intermediate goods"}]', NULL, '/ˌɪntərˈmiːdiət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/intermediate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-01', 30, 'manual', 'sách hướng dẫn; sổ tay hướng dẫn', 'noun', '[{"en":"Read the user manual carefully before using the new equipment.","vi":"Hãy đọc kỹ sách hướng dẫn sử dụng trước khi dùng thiết bị mới."},{"en":"The company gives every new employee a training manual.","vi":"Công ty phát cho mỗi nhân viên mới một cuốn sổ tay hướng dẫn đào tạo."},{"en":"The manual explains step by step how to install the software.","vi":"Sách hướng dẫn giải thích từng bước cách cài đặt phần mềm."}]', '[{"phrase":"user manual"},{"phrase":"training manual"},{"phrase":"instruction manual"},{"phrase":"consult the manual"}]', 'manual (adj): thủ công, chân tay — manual labour', '/ˈmænjuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manua/manual__us_1.mp3', NULL, NULL);
